-- Interactive Workflow Designer PRD, Phase 1 - saved workflow graphs and
-- their execution runs. Schema-per-tenant like everything else, so neither
-- table carries an explicit tenant column.
CREATE TABLE workflow_definition (
    id            UUID PRIMARY KEY,
    name          VARCHAR(200) NOT NULL,
    description   TEXT,
    graph_json    TEXT NOT NULL,
    status        VARCHAR(32) NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- id is NOT generated by Postgres (no DEFAULT) - WorkflowExecutionEngine
-- mints the UUID itself so it can be used as the workflow.events runId
-- correlation key in the very first "run started" event, before this row
-- is persisted.
CREATE TABLE workflow_run (
    id             UUID PRIMARY KEY,
    workflow_id    UUID NOT NULL,
    workflow_name  VARCHAR(200) NOT NULL,
    status         VARCHAR(32) NOT NULL,
    requested_by   VARCHAR(200),
    trace_json     TEXT,
    error_message  TEXT,
    started_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at   TIMESTAMPTZ
);

CREATE INDEX idx_workflow_run_workflow_id ON workflow_run (workflow_id, started_at DESC);
